import re,sys,os
def svg(name,size=None,color='currentColor'):
    s=f' style="width:{size}px;height:{size}px"' if size else ''
    return f'<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-label="{name}"{s}>{P[name]}</svg>'
if __name__=='__main__':
    d='/home/claude/kit/project/slides'
    for f in os.listdir(d):
        p=os.path.join(d,f);t=open(p).read()
        t2=re.sub(r'<x-icon name="([A-Za-z]+)"( style="width:(\d+)px;height:\d+px")?></x-icon>',lambda m:svg(m.group(1),m.group(3)),t)
        if t2!=t: open(p,'w').write(t2);print('fix',f)
